import { IIrbankClient } from './irbank.client.interface.js';
import { LoggerService } from '../services/logger.service.js';

export class MockIrbankClient implements IIrbankClient {
  constructor(private readonly logger: LoggerService) { }

  async fetchFinancialData(yearCode: string, fileName: string): Promise<any> {
    this.logger.info(`[MOCK] Fetching data for ${yearCode}/${fileName}`);
    if (fileName === 'fy-balance-sheet.json') return FY_BALANCE_SHEET;
    if (fileName === 'fy-cash-flow-statement.json') return FY_CASH_FLOW_STATEMENT;
    if (fileName === 'fy-profit-and-loss.json') return FY_PROFIT_AND_LOSS;
    if (fileName === 'fy-stock-dividend.json') return FY_STOCK_DIVIDEND;
    return {};
  }
}

